INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105181, 'spa', 'Lóbulo del hígado', 'El lóbulo caudado o apéndice graso del hígado, una protuberancia anatómica específica destinada a ser quemada sobre el altar en el ritual sacrificial israelita. Aparece siempre en la frase estereotipada «el apéndice sobre el hígado» junto a los riñones y el sebo en las instrucciones para holocaustos (Éx 29:13, 22), ofrendas de paz (Lv 3:4, 10, 15), ofrendas por el pecado (Lv 4:9) y ritos de consagración (Lv 8:16, 25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105186, 'spa', 'Arruinar, destruir', 'Hifil con objeto extendido: arruinar o dañar, pasando de las personas a las cosas. En 2 Reyes 3:19, Eliseo ordena a Israel ''arruinar'' cada buen terreno con piedras. Las traducciones multilingües (''arruinaréis'') cambian uniformemente del vocabulario del dolor al de la destrucción, lo que evidencia una genuina extensión semántica del sufrimiento corporal a la devastación material.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105187, 'spa', 'Estar adolorido, doler', 'Qal intransitivo: estar con dolor, doler — ya sea el cuerpo (Gn 34:25, dolor por la circuncisión) o el corazón (Pr 14:13, aflicción interior tras la alegría exterior). Las traducciones ''adoloridos'' y ''duele'' captan ambos registros, físico y emocional. La forma participial en Sal 69:29 empareja el dolor con la aflicción (עָנִי), sugiriendo la coincidencia entre sufrimiento y vulnerabilidad social.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105189, 'spa', 'Causar dolor, afligir', 'Hifil causativo: causar dolor, herir o entristecer a alguien. Job 5:18 presenta la paradoja de que Dios ''hiere pero venda'' (יַכְאִיב... יֶחֱבָשׁ), mientras que Ezequiel 13:22 acusa a quienes ''entristecieron el corazón del justo''. Las traducciones ''lo entristecí'' y ''causa dolor'' reflejan el rango que va desde la aflicción emocional hasta el daño activo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105194, 'spa', 'Dolor, sufrimiento', 'Dolor, sufrimiento o angustia que abarca tanto la dimensión física como la emocional. La palabra aparece con notable consistencia en contextos de aflicción abrumadora: Job 2:13 (amigos enmudecidos ante un sufrimiento extremo), Job 16:6 (la palabra no alivia el dolor), Sal 39:2 (dolor avivado por el silencio forzado). Proféticamente, se intensifica hacia el desastre nacional: Isaías 17:11 lo empareja con enfermedad incurable, e Isaías 65:14 contrasta el dolor de corazón con el canto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105200, 'spa', 'Desánimo interior', 'Estado emocional y espiritual de abatimiento, cobardía o quebranto de ánimo. El «quebrantado de corazón» del Salmo 109 refleja el espíritu aplastado de quien sufre persecución implacable. El rey de Daniel se acobarda ante el fracaso de sus planes, mostrando cómo los reveses militares quiebran a los orgullosos. En Ezequiel, los falsos profetas quebrantan el corazón de los justos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105201, 'spa', 'ser honrado, noble (Nifal)', 'El sentido Nifal «ser honrado, ser noble» aparece 17 veces, a menudo como participio sustantivado que significa «los honorables, los nobles». Gn 34:19 describe a Siquem como «el más honrado en la casa de su padre»; 1 S 22:14 llama a David «honrado en tu casa». Es la contraparte pasiva del sentido Piel de honrar (sentido 1), donde el sujeto recibe honor o posee estatus noble.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105202, 'spa', 'honrar, mostrar respeto (Piel)', 'El sentido Piel activo de honrar o mostrar respeto aparece 30 veces, principalmente con padres, ancianos y Dios como objetos. Éx 20:12 ordena «honra a tu padre y a tu madre»; Nm 22:17 registra la súplica de Balac a Balaam: «te honraré grandemente». El árabe كَرَّمَ («honrar»), el coreano 공경하다 y el suajili -heshimu distinguen consistentemente este sentido del peso físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105203, 'spa', 'hacer pesado, endurecer (Hifil)', 'El sentido Hifil causativo de hacer pesado, agravar o endurecer aparece 14 veces, célebremente en el endurecimiento del corazón de Faraón (Éx 8:15, 32; 9:34; 10:1). 1 Re 12:10 registra el juramento de Roboam de hacer el yugo más pesado que el de Salomón. El árabe أَثْقَلَ y el coreano 완고하게 하다 revelan la doble trayectoria: peso físico y obstinación metafórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105205, 'spa', 'ser pesado (peso físico)', 'El sentido Qal estativo de ser físicamente pesado abarca 19 ocurrencias que cubren manos, yugos, hambruna y batalla. Gn 18:20 describe el clamor de Sodoma como «grave»; Éx 5:9 ordena que la labor sea pesada sobre los israelitas. Este es el sentido raíz concreto y literal del que brotan las metáforas del honor y la carga.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105208, 'spa', 'jactarse, engrandecerse (Hitpael)', 'El sentido Hitpael reflexivo «hacerse pesado a sí mismo» — es decir, multiplicarse, jactarse o glorificarse — aparece 4 veces. 2 Cr 25:19 se burla de Amasías: «¿Por qué quieres hacerte pesado [jactarte] para tu mal?». Pr 12:9 contrasta al que se honra a sí mismo con el humilde. La forma reflexiva señala autopromoción o autoengrandecimiento, extensión negativa del sentido honorífico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105215, 'spa', 'ser glorificado (Nifal divino)', 'El sentido Nifal de que Dios sea glorificado u obtenga gloria aparece 13 veces, primordialmente en Éxodo (14:4, 17, 18) y los profetas. «Seré glorificado por medio de Faraón» muestra a Dios desplegando su peso — su gloria sustancial e innegable — mediante actos poderosos. Es un subconjunto especializado del sentido 3, donde el sujeto es divino y el contexto teofánico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105218, 'spa', 'glorificar a Dios (Piel)', 'El sentido Piel de glorificar a Dios o su nombre aparece 9 veces, contraparte activa del sentido 5. Sal 22:23 ordena «glorificadlo»; Sal 86:9 promete «glorificarán tu nombre». El árabe مَجَّدَ y el coreano 영화롭게 하다 marcan esto como lenguaje litúrgico donde el objeto es exclusivamente Dios o su nombre, no receptores humanos de honor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105221, 'spa', 'ser rico, acaudalado', 'Dos ocurrencias muestran un sentido adjetival o estativo de ser rico o acaudalado. Gn 13:2 describe a Abram como «muy pesado [rico] en ganado, plata y oro»; Pr 8:24 habla de manantiales «pesados [abundantes] de agua». Es una extensión metafórica natural: la riqueza es sustancia, peso, tener mucho. El hebreo une ambas nociones bajo la misma raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105225, 'spa', 'sea glorificado el SEÑOR (Qal optativo)', 'Job 14:21 e Is 66:5 usan el Qal imperfecto en sentido yusivo u optativo: «sea glorificado [el SEÑOR]» o «sea honrado [su nombre]». Podría pertenecer al sentido 5 (ser glorificado), pero aparece en construcción modal y no indicativa. Los datos aíslan estas dos instancias, reconociendo quizá una distinción gramatical más que semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105227, 'spa', 'honrar, engrandecer (Hifil honorífico)', 'Is 9:1 y Jer 30:19 muestran el Hifil con sentido honorífico positivo: dar honra a una tierra o pueblo, hacerlos gloriosos. Is 9:1 promete «engrandecerá el camino del mar»; Jer 30:19 asegura «los honraré». Contrasta con el sentido 4 (Hifil endurecer), mostrando que el Hifil puede expresar tanto carga como honor según el objeto y el contexto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105246, 'spa', 'endurecer el corazón (Piel/Qal)', 'Tres ocurrencias muestran el endurecimiento del corazón como construcción Piel o Qal. Éx 9:7 señala que el corazón de Faraón «se agravó»; 1 S 6:6 advierte: «¿Por qué endurecéis vuestro corazón como Egipto endureció?». Se solapa con el sentido 4 (Hifil endurecer), pero los datos separan el causativo (Hifil) del estativo/activo (Qal/Piel).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105263, 'spa', 'ser carga (uso social)', '2 S 13:25 registra «seremos carga [para ti]» como ocurrencia única en el ámbito del movimiento social. El contexto es Absalón instando al rey a no acompañarlo («para que no te seamos carga»). Parece ser un uso directo del sentido 2 (ser pesado) o del sentido 4 (hacer pesado), aplicado al contexto social de imponerse sobre alguien.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105294, 'spa', 'Peso e intensidad', 'El sustantivo aparece en cuatro contextos distintos que muestran su alcance semántico. Proverbios observa que ''el peso de la piedra'' es pesado, ilustrando que la provocación del necio lo es aún más (Pr 27:3). Nahúm describe ''la masa de cadáveres'' apilados en la conquistada Nínive (Nah 3:3). Isaías lo usa dos veces para expresar intensidad: los guerreros huyen ''de la vehemencia de la guerra'' (Is 21:15) y la ira de Dios viene con furia abrumadora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105295, 'spa', 'Pesado, severo, grave', 'Pesado, severo, grave. Sentido dominante que abarca tanto el peso literal como el figurado: fisicamente pesado (las manos de Moises en Ex 17:12, el cabello de Absalon en 2 S 14:26) y figuradamente severo o penoso (hambre grave en Gn 12:10; 41:31; 43:1, yugo oneroso en 1 R 12:4, duelo solemne en Gn 50:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105300, 'spa', 'De peso, importante', 'De peso, importante. Describe algo que tiene peso en el sentido de importante, significativo o trascendental. En 1 Reyes 3:9, Salomon pide sabiduria para juzgar al pueblo de Dios, un pueblo demasiado grande e importante para cualquier juez comun. Aqui la pesadez es social y moral, apuntando a la gravedad de la responsabilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105301, 'spa', 'Cargado, agobiado por', 'Cargado, agobiado por. Cargado o agobiado por algo, llevando el peso de la culpa o del pecado. Isaias 1:4 denuncia a Israel como un pueblo cargado de iniquidad — la nacion se tambalea bajo la carga acumulada de sus transgresiones. La construccion enfatiza la carga misma mas que la mera severidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105302, 'spa', 'Abundante, numeroso', 'Abundante, numeroso. Extension hacia la cantidad: abundante, numeroso, muy grande. La multitud mixta que salio de Egipto era sumamente abundante (Ex 12:38), usando el adjetivo casi adverbialmente para intensificar la escala del exodo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105305, 'spa', 'hígado (órgano)', 'El órgano corporal conocido como hígado, prominente en los textos sacrificiales sacerdotales donde la yoteret (''apéndice'') sobre él se quema en el altar (Éx 29:13, 22; Lv 3:4, 10, 15; 4:9; 7:4; 8:16, 25; 9:10, 19). También aparece en la hepatoscopia (Ez 21:26), una herida mortal de flecha (Pr 7:23) y el dolor derramado en angustia (Lm 2:11). Etimológicamente ''el pesado.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105310, 'spa', 'Qal intransitivo', 'Qal intransitivo: de un fuego, lámpara o llama que deja de arder, que se apaga sin que un agente lo extinga. A menudo aparece con negación para recalcar la combustión perpetua, como en los mandatos sobre el fuego del altar (Lv 6:12-13). Se usa proféticamente respecto a los fuegos del juicio divino que no se apagarán (2 R 22:17; Is 66:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105311, 'spa', 'Piel transitivo/causativo', 'Piel transitivo/causativo: apagar, extinguir o sofocar activamente un fuego o lámpara, con un agente explícito o implícito que ejecuta la acción. El Cronista registra que los sacerdotes habían cerrado el templo y apagado las lámparas (2 Cr 29:7). En sentido figurado, la metáfora de ''apagar la lámpara de Israel'' (2 Sam 21:17) advierte contra perder a David en batalla. Cantares 8:7 declara memorablemente que las muchas aguas no pueden apagar el amor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105325, 'spa', 'gloria, esplendor de Dios', 'El sentido teofánico y doxológico dominante: la radiancia visible, el esplendor y la presencia manifiesta de Dios. Es el kavod que aparece en la nube sobre el Sinaí (Éx 24:16-17), llena el tabernáculo y el templo (Éx 40:34; 1 Re 8:11) y que Isaías contempla entronizado (Is 6:3). Las 170 ocurrencias confirman este como el significado abrumadoramente primario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105328, 'spa', 'honor, respeto, dignidad', 'Honor, estima y dignidad otorgados a una persona humana — 26 ocurrencias. Este sentido aparece en la literatura sapiencial y en contextos regios: Salomón recibe kavod junto con riqueza (1 Cr 29:12, 28; 2 Cr 1:11), y Proverbios enseña que la humildad precede al kavod (Pr 15:33; 18:12). El español honor y el francés gloire aparecen en estos pasajes, distinguiéndose del sentido teofánico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105354, 'spa', 'riqueza, abundancia', 'Riqueza material, bienes y abundancia — un sentido reducido pero etimológicamente significativo que aparece claramente en Gn 31:1 (Jacob tomó todo el kavod de Labán) y Nah 2:9 (el saqueo del kavod de Nínive). Aquí la metáfora del «peso» es más concreta: kavod es la masa pura de posesiones. El francés richesse y el árabe ثروة confirman este sentido como genuinamente distinto de «honor».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105355, 'spa', 'honra personal, dignidad íntima', 'Honor personal o dignidad interior en contexto poético-tribal. En Gn 49:6 la bendición de Jacob declara «no entre mi kavod en su asamblea», refiriéndose a su honra personal o fuerza vital. La forma femenina usada aquí (única en el corpus) y el paralelismo con nephesh («alma») sugieren que kavod funciona como cuasi-sinónimo de la esencia o la reputación de uno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105362, 'spa', 'gloria colectiva de un pueblo', 'La gloria o el esplendor colectivo de un pueblo o nación — como en Is 5:13 donde el kavod de Israel marcha al exilio junto con su multitud. El español sus nobles, el alemán seine Herrlichkeit y el inglés its glory muestran que los traductores divergen sobre si se trata del honor de la nación, su clase dirigente o su esplendor. El paralelismo con hamón («multitud») sugiere que kavod abarca aquí la grandeza total de la comunidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105375, 'spa', 'Poderoso, fuerte', 'Poder personal o autoridad soberana, aplicado a Dios o a individuos fuertes. Job lo emplea para la majestad divina (Job 34:17, 36:5) y para guerreros (Job 34:24). La doble aparición en Job 36:5 — ''poderoso en fuerza de entendimiento'' — muestra que puede denotar tanto poder intelectual como físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105376, 'spa', 'Grande, impetuoso', 'Grandeza o fuerza aplicada a fenómenos y fuerzas naturales impersonales. Las ''aguas impetuosas'' de Isaías (Isa 17:12, 28:2) y el ''viento impetuoso'' de Bildad (Job 8:2) ilustran este sentido. Job 15:10 lo usa para la edad avanzada — ''mayor que tu padre en días'' — extendiendo la idea de ''grandeza'' a la duración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105381, 'spa', 'Mucho, abundante', 'Abundancia o cantidad pura, distinta de poder o fuerza. Job 31:25 — ''porque mi mano había adquirido mucho'' — es la única atestación. El sentido señala riqueza material en vez de poder personal o fuerza natural, marcando claramente un uso cuantitativo más que cualitativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105384, 'spa', 'Lavar, limpiar (Piel activo) — El sentido activo principal en Piel', 'Lavar, limpiar (Piel activo) — El sentido activo principal en Piel: lavar, limpiar o blanquear prendas y telas pisoteándolas o amasándolas en agua. Es con mucho el uso más frecuente, y aparece en la legislación ritual de Levítico y Números donde las prendas contaminadas deben ser lavadas (Lv 11:25; 13:6; 15:5). En Génesis 49:11, Judá figuradamente «lava su ropa en vino», una imagen impactante de abundancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105386, 'spa', 'Lavador, batanero (participio) — El sentido participial o sustantivado que desig', 'Lavador, batanero (participio) — El sentido participial o sustantivado que designa a un lavador o batanero profesional de telas. El «campo del batanero» (שְׂדֵה כוֹבֵס) cerca de Jerusalén aparece como punto de referencia geográfico en tres pasajes paralelos (2 Re 18:17; Is 7:3; 36:2). Malaquías 3:2 usa el participio plural מְכַבְּסִים para describir la obra purificadora del mensajero de Dios: «como jabón de lavanderos». En español «lavador» y en francés «fouler» preservan la idea del oficio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105387, 'spa', 'Ser lavado (Hitpael reflexivo) — El sentido reflexivo o recíproco en Hitpael', 'Ser lavado (Hitpael reflexivo) — El sentido reflexivo o recíproco en Hitpael: ser lavado o someterse al lavado. Aparece únicamente en Levítico 13:55-56 en el contexto de inspeccionar prendas para detectar marcas persistentes de enfermedad cutánea después del lavado. La conjugación reflexiva presenta la prenda misma como sujeto del proceso, vista desde la perspectiva de la tela que es sometida a la limpieza y no del agente que la realiza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105390, 'spa', 'Ser lavado (Pual pasivo) — El sentido pasivo en Pual', 'Ser lavado (Pual pasivo) — El sentido pasivo en Pual: ser lavado, indicando que la prenda es receptora de la acción de lavado sin especificar el agente. Se encuentra en Levítico 13:58 (una prenda cuya marca desaparece tras el lavado) y 15:17 (tela sobre la cual hay una emisión corporal que debe ser lavada). En español «será lavado» capta con precisión la construcción pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105403, 'spa', 'Ya, previamente', 'Adverbio temporal que significa ''ya, previamente'', marcando una acción o estado como ocurrido antes del momento presente. Limitado por completo a Eclesiastés, sirve al argumento de Qohélet sobre la futilidad de la novedad: lo que existe ''ya ha sido'' en épocas pasadas (Ecl 1:10; 3:15). El español ''ya'' capta el sentido con precisión. La frecuencia de esta palabra en el hebreo mishnaico y sus cognados en arameo y siríaco confirman su carácter tardío dentro del hebreo bíblico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105404, 'spa', 'Río Quebar', 'Nombre propio de un río o canal babilónico (nehar Kevar) donde se asentaron los exiliados judíos y donde Ezequiel recibió sus visiones proféticas. Las ocho apariciones se encuentran en Ezequiel (1:1, 3; 3:15, 23; 10:15, 20, 22; 43:3), siempre en la frase fija ''el río Quebar''. El sitio probablemente corresponde a un canal cerca de Nippur.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105405, 'spa', 'Distancia indeterminada', 'Distancia indeterminada pero aparentemente corta, quizás lo que se puede divisar o recorrer en poco tiempo. La frase subraya la trágica cercanía de Raquel a su destino: tan cerca y a la vez demasiado lejos, muriendo a la vista de Belén. La vaguedad del término en las traducciones refleja una genuina incertidumbre sobre la medida exacta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105407, 'spa', 'cordero, oveja joven macho', 'Oveja joven macho especificada para contextos sacrificiales y de ofrenda: holocaustos, ofrendas por el pecado, sacrificios de paz, ritos de purificación y prescripciones festivas a lo largo de toda la legislación sacerdotal. Solo la ofrenda diaria requiere dos corderos (Éx 29:38-39; Nm 28:3-4), y Números 7 los enumera repetidamente en la dedicación tribal del altar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105417, 'spa', 'como cordero (símil)', 'Usado en construcciones comparativas (con el prefijo כְּ) para comparar a una persona con un cordero, evocando inocencia, mansedumbre o vulnerabilidad. Jer 11:19 — «era como cordero manso llevado al matadero» — anticipa la imaginería del Siervo Sufriente de Isaías 53, mientras que Os 4:16 compara al Israel descarriado con «un cordero en amplia pradera». Estos dos pasajes transforman un término cultico en metáfora profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105427, 'spa', 'Ser sometido o conquistado en el Nifal pasivo', 'Ser sometido o conquistado en el Nifal pasivo: tierra o territorio que ha sido puesto bajo control. Números 32:22 y Josué 18:1 emplean esta forma para describir a Canaán ''sometida'' ante el SEÑOR. El paso de conquista activa a estado consumado es importante: 1 Crónicas 22:18 presenta la tierra ya subyugada, fundamento teológico para la construcción del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105428, 'spa', 'Forzar o violar sexualmente en el Qal', 'Forzar o violar sexualmente en el Qal: uso especializado y perturbador donde la subyugación física se convierte en agresión sexual. En Ester 7:8, el rey interpreta la postura de Hamán cerca de Ester como un intento de ''someter'' (violar) a la reina. BDB señala el paralelo con el término hebreo anterior עִנָּה.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105429, 'spa', 'Someter o conquistar en el Qal', 'Someter o conquistar en el Qal: sentido fundamental de poner bajo dominio por la fuerza. Génesis 1:28 emplea el imperativo — la humanidad recibe el encargo de ''someter'' la tierra como mayordomos. Miqueas 7:19 lo aplica metafóricamente: Dios ''someterá'' las iniquidades de Israel, pisoteándolas. El cognado árabe ''kabasa'' (prensar, apretar) conserva la idea de fuerza física aplicada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105433, 'spa', 'Subyugar por la fuerza en el Hifil causativo', 'Subyugar por la fuerza en el Hifil causativo: obligar a otros a la servidumbre o la esclavitud. Jeremías 34:11 registra a los nobles forzando a los esclavos liberados a volver a la servidumbre — una violación del pacto que provoca el juicio divino. La raíz causativa enfatiza la agencia coercitiva del opresor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105435, 'spa', 'Conquistar completamente en el Piel intensivo', 'Conquistar completamente en el Piel intensivo: subyugación total de pueblos conquistados, con la raíz Piel enfatizando exhaustividad o repetición. En 2 Samuel 8:11, David consagra el botín de naciones que había ''sometido'' — la forma intensiva subraya el dominio militar absoluto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105442, 'spa', 'Corderita (oveja hembra)', 'Oveja joven hembra, forma femenina de כֶּבֶשׂ (cordero). Se emplea en la celebración de pactos (Gn 21:28-30, las siete corderitas de Abraham en Beerseba), en la ley sacrificial para ofrendas de purificación y del nazareato (Lv 14:10; Nm 6:14), y de modo especialmente memorable en la parábola de Natán sobre la amada corderita del pobre (2 S 12:3-6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105447, 'spa', 'Horno o calera', 'El término aparece exclusivamente en comparaciones vívidas y relatos de plagas. Abraham vio el humo de las ciudades destruidas subir ''como humo de un horno'' (Gn 19:28). Moisés y Aarón tomaron ''ceniza de un horno'' y la esparcieron para producir la plaga de úlceras (Éx 9:8, 10). El monte Sinaí ''humeaba como un horno'' cuando Yahvé descendió en fuego (Éx 19:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105448, 'spa', 'Cántaro, tinaja, jarra', 'Cántaro, tinaja, jarra: un recipiente de barro de tamaño mediano diseñado para transportar o almacenar líquidos y productos secos. La escena de Rebeca junto al pozo (Gn 24) muestra cómo se equilibraba sobre el hombro de una mujer para transportar agua, mientras que la tinaja de la viuda en 1 R 17 contenía harina. Los guerreros de Gedeón usan cántaros vacíos para ocultar antorchas (Jue 7:16). Eclesiastés emplea la imagen del cántaro roto junto a la fuente como conmovedora metáfora de la muerte (Ec 12:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105460, 'spa', 'Rey de Elam', 'Nombre propio del rey de Elam que encabezó una coalición de cuatro reyes contra las ciudades de la llanura del Jordán en Génesis 14. Todas las traducciones principales conservan una forma reconocible: en español ''Quedorlaomer'', en inglés ''Chedorlaomer''. El nombre deriva del acadio/elamita Kudur-Lagamar (''siervo de Lagamaru''). Sus cinco apariciones se concentran en Génesis 14:1-17.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105461, 'spa', 'así, de este modo', 'El adverbio de manera: «así», «de este modo» — el sentido abrumadoramente dominante, hallado 569 veces. Casi siempre apunta hacia adelante, hacia lo que sigue, especialmente en la fórmula profética del mensajero «así dice el SEÑOR» (כֹּה אָמַר יְהוָה), que por sí sola abarca cientos de ocurrencias. También se usa en discurso indirecto («así dijo», Gn 32:4) y descripciones comparativas («así será tu descendencia», Gn 15:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105465, 'spa', 'aquí, allí, hacia acá', 'Demostrativo espacial: «aquí», «allí», «hacia acá». Aparece en el modismo pareado כֹּה וָכֹּה que significa «aquí y allá» o «a un lado y al otro» (Éx 2:12, donde Moisés mira «a uno y otro lado»). También se emplea independientemente como «aquí» (Gn 22:5, «quédense aquí con el asno») o direccionalmente como «acá» (Nm 23:15). La evidencia multilingüe se divide reveladoramente: el español usa tanto aquí como allá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105467, 'spa', 'ahora, hasta este momento', 'Una extensión temporal infrecuente: «ahora», «hasta este momento», atestiguada en Éx 7:16 donde el mensaje de Dios incluye la declaración de que Faraón no ha escuchado «עַד־כֹּה» — «hasta ahora». La fuerza demostrativa se desplaza de la proximidad espacial a la inmediatez temporal. Las glosas multilingües confirman con ahora (español), maintenant (francés) y nun (alemán), todos adverbios temporales estándar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105474, 'spa', 'Oscurecerse, debilitarse', 'Oscurecerse, perder fuerza o brillo — usado principalmente de ojos que fallan por vejez (Gn 27:1; Dt 34:7), por aflicción (Job 17:7) o por juicio divino (Zac 11:17), y figuradamente de una persona que no desfallece bajo la prueba (Is 42:4, del Siervo del Señor, comparado con una lámpara que no se apaga) y del espíritu humano que se debilita de consternación (Ez 21:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105482, 'spa', 'Tenue, desvanecido, apagado', 'Adjetivo femenino (de la raíz כ-ה-ה) que indica brillo, color o vitalidad disminuidos. En el sistema diagnóstico sacerdotal de Levítico 13, aparece seis veces como indicador clave de que una afección cutánea es benigna: si la marca se ha vuelto כֵּהָה (''tenue, desvanecida''), la persona es declarada limpia (Lv 13:6). Se aplica también a los ojos de Elí debilitados por la edad (1 S 3:2) y a la mecha que arde tenuemente según Isaías 42:3.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105489, 'spa', 'Capacidad o habilidad', 'El verbo aparece cuatro veces en las secciones arameas de Daniel, siempre en contextos negativos de incapacidad humana ante misterios divinos. El rey pregunta a Daniel: ''¿Puedes tú darme a conocer el sueño?'' (Dn 2:26), esperando el mismo fracaso que los demás sabios. El rey describe el sueño como uno que ''tú puedes interpretar'' (Dn 4:18), reconociendo la capacidad única de Daniel otorgada por el Espíritu.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105490, 'spa', 'Ejercer el oficio sacerdotal, desempeñando funciones litúrgicas como ofrecer sac', 'Ejercer el oficio sacerdotal, desempeñando funciones litúrgicas como ofrecer sacrificios, ministrar en el altar y servir en el santuario. El tronco Piel marca esta acción como denominativa: se actúa como כֹּהֵן. Las traducciones al español como ejercer-sacerdocio reflejan la naturaleza profesional y continua de este ministerio (Éx 28:1, 41; Lv 16:32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105494, 'spa', 'Adornarse o engalanarse al modo de un sacerdote que se reviste con sus vestidura', 'Adornarse o engalanarse al modo de un sacerdote que se reviste con sus vestiduras, usado metafóricamente del novio (Isa 61:10). La evidencia multilingüe confirma el cambio de la función ritual a la exhibición ornamental, donde el atuendo sacerdotal se convierte en símil de esplendor festivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105503, 'spa', 'Sacerdote, oficiante cultual', 'Persona consagrada al servicio cultual, encargada de ofrecer sacrificios, mantener el santuario y mediar entre la divinidad y la comunidad. Abarca a los sacerdotes aarónicos y levíticos (Éx 29:30), al rey-sacerdote Melquisedec (Gn 14:18), a los oficiantes paganos (2 R 10:19) y al sacerdote escatológico de Zacarías 6:13. El arameo כָּהֲנָא y el etiópico kahen atestiguan la profunda raíz semítica del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105525, 'spa', 'Sacerdote(s)', 'Funcionario cúltico que servía en el templo de Jerusalén. Las ocho apariciones se agrupan en torno a las actividades del templo en la era de la restauración: ofrecer sacrificios (Esd 6:9), dedicar la casa reconstruida (Esd 6:16), organizar turnos de servicio (Esd 6:18) y exenciones reales de tributación (Esd 7:24). La forma singular determinada kahanāʾ designa al propio Esdras como ''el sacerdote, escriba de la ley del Dios del cielo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105529, 'spa', 'El oficio sacerdotal y sus privilegios hereditarios dentro de la línea aarónica-', 'El oficio sacerdotal y sus privilegios hereditarios dentro de la línea aarónica-levítica. Establecido como perpetuo en Éxodo 29:9 y 40:15, custodiado con lenguaje de límites en Números 18:1, 7. Finees lo recibe como pacto eterno (Núm 25:13). Josué 18:7 lo identifica como la porción de los levitas en lugar de tierra. Los textos postexílicos (Esd 2:62; Neh 7:64; 13:29) lo aplican a la legitimidad genealógica y la exclusión de quienes no podían demostrar su linaje.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105538, 'spa', 'Casco militar', 'Pieza de armadura militar llevada sobre la cabeza para protección en combate. Aparece como armadura de bronce: sobre Goliat (1 Sam 17:5, כּוֹבַע נְחֹשֶׁת), en el ejército de Uzías (2 Cr 26:14), entre guerreros egipcios (Jer 46:4) y mercenarios de Tiro (Ez 27:10; 38:5). Figuradamente, Isaías 59:17 lo transforma en armadura divina: Dios viste un ''yelmo de salvación''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105544, 'spa', 'Estrella, cuerpo celeste', 'Estrella, cuerpo celeste. Cuerpo celeste luminoso visible en el cielo nocturno, con funciones tanto literales como figuradas. Literalmente, las estrellas son objetos creados el cuarto dia (Gn 1:16), nombradas y contadas por Dios (Sal 147:4; Is 40:26). Figuradamente representan: (a) lo innumerable en la promesa abrahamica (Gn 15:5; 22:17; Dt 1:10; 28:62), (b) destino real o mesianico en el oraculo de Balaam (Nm 24:17), (c) agentes cosmicos en el juicio divino (Is 13:10; Jl 2:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105560, 'spa', 'Contener, albergar (capacidad)', 'Contener, albergar (capacidad). Capacidad fisica: sostener o contener dentro de un espacio definido. El Mar de bronce de Salomon ''contenia'' dos mil batos (1 R 7:26, 38). Lo mas teologicamente impactante: la oracion de Salomon se maravilla de que los cielos y los cielos de los cielos no pueden ''contener'' a Dios (1 R 8:27; 2 Cr 2:6; 6:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105561, 'spa', 'Sustentar, proveer, alimentar', 'Sustentar, proveer, alimentar. Significado principal del Pilpel: sustentar, proveer o alimentar a alguien a lo largo del tiempo, especialmente suministrando comida. Jose promete כִּלְכֵּל a la casa de su padre durante el hambre (Gn 45:11; 50:21); Barzilay sustento a David en Mahanaim (2 S 19:32-33); el hijo de Rut sustentara a Noemi en la vejez (Rt 4:15); Abdias sustento a cien profetas con pan y agua (1 R 18:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105564, 'spa', 'Soportar, resistir, aguantar', 'Soportar, resistir, aguantar. Extension psicologico-emocional: soportar, aguantar o resistir algo abrumador. Jeremias describe la palabra de Dios como fuego encerrado en sus huesos — esta cansado de ''contenerla'' y no puede (Jer 20:9). Malaquias 3:2 pregunta quien podra ''soportar'' el fuego del refinador. Joel 2:11 pregunta quien podra ''resistir'' el terrible Dia del SENOR.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105566, 'spa', 'Administrar, gestionar', 'Administrar, gestionar. En Salmo 112:5, la persona justa ''administra'' o ''gestiona'' sus asuntos con justicia. Esto extiende el sentido de sustentar al ambito de la administracion prudente — manejar los propios negocios y recursos con discernimiento, tendiendo un puente entre el sentido de ''proveer'' y el de ''contener''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105584, 'spa', 'Aprovisionar (para batalla)', 'Aprovisionar (para batalla). Un unico uso en 1 Reyes 20:27, donde los israelitas fueron ''aprovisionados'' antes de la batalla contra el vasto ejercito sirio de Ben-hadad. Extension natural del sentido ''sustentar/alimentar'' al contexto de la logistica militar, donde las tropas deben ser alimentadas y equipadas antes del combate.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105593, 'spa', 'Preparar, disponer (Hifil)', 'Acepción Hifil de preparar o disponer algo, la más frecuente con 80 apariciones. Gn 43:16 narra a José mandando preparar una comida; Nm 23:1 describe a Balaam preparando siete altares. El árabe أَعَدَّ (''preparar de antemano'') y el suajili -andaa (''preparar'') confirman esta acepción causativa de acción deliberada para dejar algo listo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105596, 'spa', 'Estar establecido, firme (Nifal)', 'Acepción Nifal pasiva/estativa con 42 apariciones: ''estar establecido, mantenerse firme''. Gn 41:32 explica que el sueño se repitió porque ''la cosa está establecida por Dios''; 2 S 7:16 promete que ''tu trono será establecido para siempre''. El árabe يَثْبُتُ (''ser firme, perdurar'') señala un estado de permanencia distinto de la mera preparación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105599, 'spa', 'Establecer, afirmar (Hifil)', 'Acepción Hifil causativa de establecer o instaurar un reino, trono o persona, con 28 apariciones. 1 S 13:13 relata que el reino de Saúl habría sido establecido; 2 S 7:12-13 promete que Dios establecerá el trono de Salomón. El árabe ثَبَّتَ y أَقَامَ distinguen esta acepción de la mera preparación: el énfasis recae en hacer que algo se mantenga firme.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105601, 'spa', 'Listo, preparado (Nifal)', 'Participio Nifal usado como adjetivo para ''listo, preparado'', con 17 apariciones. Ex 19:11 ordena al pueblo ''estar preparados para el tercer día''; Jos 8:4 instruye a la emboscada a estar lista. El árabe مُسْتَعِدّ (''listo, preparado'') revela un estado de disposición para la acción, no de firmeza permanente, un matiz distinto dentro del Nifal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105611, 'spa', 'Correcto, cierto (Nifal)', 'Participio Nifal con el sentido de ''correcto, cierto, verdadero'', 9 apariciones en contextos legales y epistémicos. Dt 13:14 manda investigar ''y si resulta cierto'' que hubo idolatría; 1 S 23:23 busca ''conocimiento certero'' de la ubicación de David. El árabe صَوَابًا (''rectitud'') y يَقِين (''certeza'') distinguen esta acepción ético-epistémica de la firmeza física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105615, 'spa', 'Confirmar, fundar (Piel)', 'Acepción Piel intensiva de confirmar o fundar con firmeza, con 24 apariciones. Ex 15:17 celebra el monte que Dios ha fundado; 2 S 7:24 describe a Dios estableciendo a Israel como su pueblo. El árabe ثَبَّتَ (intensivo de ''hacer firme'') y أَسَّسَ (''fundar, poner cimiento'') reflejan el acto deliberado e intensivo de establecer con énfasis en la durabilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105624, 'spa', 'Mantenerse firme', 'Jos 3:17 y 4:3 describen a los sacerdotes de pie ''firmes'' sobre tierra seca en el Jordán. El contexto y la forma Nifal estativa sugieren que esta acepción podría pertenecer a la acepción 2 (estar establecido, mantenerse firme) más que constituir un grupo independiente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105631, 'spa', 'Ser establecido (Pual/Hofal)', 'Formas pasivas Pual y Hofal (5 apariciones) que expresan ser establecido o preparado por un agente externo. Sal 37:23 declara que los pasos del hombre son establecidos por el SEÑOR; Zac 5:11 describe una casa siendo dispuesta para el efa. El árabe مُعَدّ (''preparado'') y يُثَبَّتُ (''es hecho firme'') confirman la voz pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105640, 'spa', 'Establecerse (Hitpael)', 'Acepción reflexivo-pasiva del Hitpael con 3 apariciones. Nm 21:27 llama a que Hesbón sea establecida (edificada); Pr 24:3 describe una casa que se establece mediante la prudencia; Is 54:14 promete ''serás establecida en justicia''. El árabe يَسْتَعِدّ (''prepararse a sí mismo'') marca la naturaleza reflexiva o autodirigida de la acción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105641, 'spa', 'Dirigir, apuntar (Hifil/Piel)', 'Cuatro apariciones muestran una extensión semántica de dirigir o apuntar hacia un objetivo. Sal 21:12 habla de apuntar flechas al rostro de los enemigos; Jr 10:23 declara que los pasos del hombre no son dirigidos por él mismo. El árabe تُصَوِّبُ (''apuntar a'') revela una genuina extensión del establecimiento a la orientación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105709, 'spa', 'Preparar flechas (Piel)', 'Sal 11:2 e Is 51:13 describen el acto de colocar o preparar flechas en la cuerda del arco, una acepción Piel especializada en la preparación de armamento. El árabe أَعَدُّوا (''prepararon [armas]'') en contextos militares confirma esta extensión técnica de la acepción de preparación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105712, 'spa', 'Ser formado', 'Ez 16:7 emplea una forma glosada como ''fueron formados'' en el contexto del desarrollo corporal (''tus pechos se formaron''). Esta única aparición con contexto biológico podría representar una extensión especializada de la acepción 2 (ser establecido) o de la acepción 7 (ser preparado pasivamente).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105744, 'spa', 'Konanyahu (nombre propio)', 'Nombre teofórico hebreo (''Yahveh ha establecido'') que designa a líderes levíticos en Crónicas. En español se emplea ''Conanías'' o ''Konanyahu''. El portador principal supervisaba los almacenes del templo donde se guardaban diezmos y ofrendas bajo Ezequías (2 Cr 31:12-13); un segundo aparece como contribuyente levítico en la Pascua de Josías (2 Cr 35:9). La LXX varía entre formas como Χωνενιας.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105749, 'spa', 'Un recipiente para beber vino u otras bebidas, presente en contextos narrativos ', 'Un recipiente para beber vino u otras bebidas, presente en contextos narrativos literales como el sueño del copero (Gn 40:11-21), la parábola de Natán (2 S 12:3) y la negativa de los recabitas (Jer 35:5). También describe el borde ornamental del mar de bronce de Salomón (1 R 7:26). El uso concreto sirve de base para las extensiones metafóricas más ricas en la literatura profética y sapiencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105763, 'spa', 'Búho pequeño', 'Especie pequeña de búho, probablemente nocturno, asociado con ruinas y lugares desolados. La comparación del salmista con un búho entre ruinas transmite con fuerza el aislamiento, el duelo y la alienación de la vida humana normal. Su condición de ave impura en la ley levítica se relaciona posiblemente con sus hábitos carroñeros o su naturaleza nocturna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105764, 'spa', 'Horno, crisol de fundición', 'Sustantivo masculino que designa un horno de fundición o crisol para metales, empleado consistentemente en contextos metafóricos y de símil para la prueba, el castigo o la purificación divina. Emergen tres grandes imágenes: (a) Egipto como ''el horno de hierro'' de la esclavitud (Dt 4:20; 1 R 8:51; Jr 11:4); (b) el crisol del refinador que prueba el carácter como el fuego prueba el oro (Pr 17:3; 27:21); (c) Israel como metales impuros en el horno de Dios (Ez 22:18-22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105771, 'spa', 'El nombre propio כּוֹרֶשׁ, que identifica a Ciro II de Persia (r', 'El nombre propio כּוֹרֶשׁ, que identifica a Ciro II de Persia (r. 559–530 a.C.), conquistador de Babilonia y libertador de los exiliados judíos. Llamado ''ungido'' del SEÑOR en Isaías 45:1 — designación asombrosa para un gentil — y ''mi pastor'' en Isaías 44:28. Su edicto que autorizó la reconstrucción del templo se registra en 2 Crónicas 36:22–23 y Esdras 1:1–4. La evidencia multilingüe muestra notable consistencia en la preservación del nombre: Ciro, Cyrus, Kyrus.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105775, 'spa', 'Koresh (Ciro)', 'El rey persa Ciro el Grande, cuyo edicto autorizó la reconstrucción del templo de Jerusalén. En Esdras 5:13–17 y 6:3 se lo cita como autor del decreto que Sesbasar ejecutó; en Daniel 6:29 aparece como sucesor de Darío el Medo. El nombre funciona como ancla histórico-política que vincula la narrativa de la restauración con la cronología imperial verificable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105777, 'spa', 'Nombre propio del territorio al sur de Egipto a lo largo del alto Nilo (Nubia/Et', 'Nombre propio del territorio al sur de Egipto a lo largo del alto Nilo (Nubia/Etiopía) y del antepasado epónimo, hijo de Cam y padre de Nimrod (Gn 10:6-8). Geográficamente marca el horizonte meridional extremo: ''desde la India hasta Cus'' abarca el Imperio Persa (Est 1:1; 8:9). Proféticamente, Cus aparece en oráculos de juicio contra los aliados de Egipto (Ez 30:4-5; 38:5) y en promesas de adoración universal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105786, 'spa', 'Gentilicio que designa a una persona o pueblo procedente de Cus, al sur de Egipt', 'Gentilicio que designa a una persona o pueblo procedente de Cus, al sur de Egipto. Se aplica a individuos específicos — el corredor cusita (2 S 18:21-32), Ebed-melec el cusita (Jer 38:7) — y colectivamente a la nación (Sof 2:12; 2 Cr 14:11). La forma femenina כֻּשִׁית aparece únicamente para referirse a la esposa de Moisés (Nm 12:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105799, 'spa', 'Rey opresor mesopotámico', 'Cusán-Risataim aparece cuatro veces en Jueces 3, dos veces presentado como ''Cusán-Risataim rey de Aram-Naharaim'' a quien Yahvé vendió a Israel en juicio (Jue 3:8), y dos veces como el opresor al que Israel sirvió ocho años hasta que Otoniel lo derrotó (Jue 3:10). La Septuaginta lo transcribe como Χουσαρσαθαιμ o Χουσανρεσαμωθ, mostrando los intentos griegos de reproducir el doble nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105802, 'spa', 'Mentiras (sustantivo)', 'Mentiras (sustantivo): uso sustantivado donde el participio o forma verbal funciona como sustantivo con el significado de ''mentiras'' o ''falsedades'' — el contenido producido por el acto de mentir. Ambas apariciones se encuentran en Jueces 16, donde Dalila acusa a Sansón: ''me has dicho mentiras'' (Jue 16:10, 13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105803, 'spa', 'Mentir, decir mentiras (Piel)', 'Mentir, decir mentiras (Piel): engaño verbal activo en la forma Piel: decir lo que no es verdad, mentir deliberadamente. Es el uso principal y más frecuente, que abarca tanto la mentira absoluta (Nm 23:19; Job 6:28) como la mentira dirigida a alguien (Sal 78:36; Ez 13:19). Proverbios 14:5 contrasta al testigo fiel con el que ''profiere mentiras''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105804, 'spa', 'Fallar, resultar engañoso (Piel)', 'Fallar, resultar engañoso (Piel): sentido extendido del Piel aplicado a cosas en vez de personas: fallar, decepcionar o resultar engañoso. En Isaías 58:11 describe aguas que ''no fallan'' — manantiales cuyo caudal nunca engaña al sediento. Esta extensión metafórica del mentir personal al fallar impersonal tiene paralelos en los cognados árabes y arameos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105811, 'spa', 'Ser hallado falso (Nifal)', 'Ser hallado falso (Nifal): la forma Nifal (pasiva/reflexiva) que significa ser hallado falso, resultar mentiroso o mostrarse engañoso. En Job 41:9 describe una esperanza que ''resulta vana'', y en Proverbios 30:6 advierte contra añadir a las palabras de Dios ''no sea que seas hallado mentiroso''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105814, 'spa', 'Probar a alguien mentiroso (Hifil)', 'Probar a alguien mentiroso (Hifil): la forma causativa Hifil: probar a alguien mentiroso, convencer de falsedad. Job 24:25 pregunta ''¿quién me desmentirá?'' — desafiando a sus oponentes a demostrar que sus palabras son falsas. Es la única aparición del Hifil de esta raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105817, 'spa', 'Mentiroso (participio Qal)', 'Mentiroso (participio Qal): el participio activo Qal usado como sustantivo: ''un mentiroso'', describiendo el carácter habitual de una persona. El Salmo 116:11 declara ''todo hombre es mentiroso'' (כֹּל הָאָדָם כֹּזֵב), una sentencia universal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105819, 'spa', 'Una falsedad deliberada o declaración engañosa que se presenta como la antítesis', 'Una falsedad deliberada o declaración engañosa que se presenta como la antítesis moral y teológica de la verdad. Predomina en el retrato proverbial del testigo falso (Pr 6:19; 14:5, 25; 19:5, 9) y en la condena de Ezequiel contra los profetas que adivinan mentiras en nombre de YHWH (Ez 13:6-9; 22:28). En los Salmos, buscar כָּזָב indica traición espiritual (Sal 4:2; 62:4). Oseas lo vincula con la perfidia del pacto (Os 7:13; 12:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105829, 'spa', 'Fuerza, vigor, poderío', 'Fuerza física o general: la acepción dominante con 115 apariciones. Abarca la fuerza bruta de Sansón (Jue 16:17), el vigor que sostiene el alimento (1 R 19:8), la fuerza que decae en la vejez (Sal 71:9) y el poderío divino en los actos cósmicos (Jr 10:12; 27:5). El árabe quwwa, el coreano 힘 y el alemán Kraft convergen en este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105839, 'spa', 'Poder, capacidad', 'Poder como capacidad, aptitud o facultad de lograr algo: 10 apariciones donde el énfasis pasa de la fuerza bruta a la competencia. En Ex 9:16 Dios dice a Faraón ''te he levantado para mostrarte mi poder''; en Esd 2:69 los retornados dan ''según su capacidad''. El árabe al-qudra (''capacidad'') y el coreano 능력 (''habilidad'') marcan esta distinción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105858, 'spa', 'Riqueza, recursos', 'Riqueza, recursos o bienes: una acepción marginal con una sola aparición en Job 6:22, donde Job pregunta ''¿Acaso dije: Dadme algo de vuestra riqueza/fuerza?'' Los glosarios multilingües se dividen entre ''riqueza'' y ''fuerza''. BDB registra esta extensión donde כֹּחַ denota el producto material o los recursos que la fuerza genera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105873, 'spa', 'Ocultar, esconder (Piel)', 'Ocultar, esconder (Piel). Ocultacion deliberada de informacion o verdad en el tronco Piel — el grupo mas numeroso con 15 apariciones. Alguien retiene o suprime intencionalmente un conocimiento de otra persona. El pasaje clasico es la solemne exigencia de Eli a Samuel: ''No me lo ocultes'' (1 S 3:17-18), repetido con enfasis duplicado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105876, 'spa', 'Ser cortado, perecer (Nifal)', 'Ser cortado, perecer (Nifal). Ser cortado, destruido o perecer — el tronco Nifal en su sentido destructivo, con 7 apariciones. Aqui el pasivo de kachad no significa ''ser ocultado'' sino ''ser borrado de la existencia''. Job 4:7 pregunta ''donde fueron cortados los rectos''; Job 15:28 habla de ciudades que son nikhadot — ''cayendo en ruina'', literalmente ''siendo borradas''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105885, 'spa', 'Aniquilar, destruir (Hifil)', 'Aniquilar, destruir (Hifil). Aniquilacion o destruccion causativa en el tronco Hifil — 5 apariciones del sentido mas violento. Dios promete ''exterminar'' a las naciones ante Israel (Ex 23:23), y este es el tronco usado para la aniquilacion de la casa de Jeroboam (1 R 13:34). En Sal 83:4 los enemigos conspiran para ''destruir'' a Israel como nacion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105886, 'spa', 'Estar oculto (Nifal pasivo)', 'Estar oculto (Nifal pasivo). Estar oculto o escondido de la vista o del conocimiento — el Nifal en su sentido pasivo de ocultacion, con 4 apariciones. Es la contraparte pasiva del Piel del sentido 1: lo que el Piel oculta activamente, el Nifal lo describe como en estado de ocultamiento. En 2 S 18:13, ningun asunto puede ''ocultarse'' del rey; en Sal 139:15, la estructura del salmista no estaba ''oculta'' de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105891, 'spa', 'Esconder con deleite (Hifil)', 'Esconder con deleite (Hifil). Una unica aparicion Hifil en Job 20:12 donde el malvado ''esconde'' el mal bajo su lengua — ocultandolo como algo que se saborea, no como informacion retenida. El tronco Hifil y la metafora gustativa (el mal es dulce en la boca, escondido bajo la lengua) le otorgan un matiz distintivo: no es mera supresion sino goce secreto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105903, 'spa', 'Negar la verdad, mentir u obrar con falsedad hacia alguien', 'Negar la verdad, mentir u obrar con falsedad hacia alguien. Es el sentido principal del Piel, que abarca catorce de las veintidós ocurrencias. Va desde la negación temerosa de Sara ante el Señor (Gn 18:15) hasta las prohibiciones legales contra jurar falsamente sobre un depósito o un objeto hallado (Lv 6:2-3; 19:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105904, 'spa', 'Someterse con temor o fingir obediencia ante un conquistador', 'Someterse con temor o fingir obediencia ante un conquistador. Los enemigos derrotados ''se someten fingidamente'' al vencedor (Dt 33:29; 2 S 22:45), con una sumisión exterior que enmascara la resistencia interior. El engaño es performativo: los cuerpos se inclinan mientras los corazones se rebelan (Sal 81:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105914, 'spa', 'Fallar, resultar engañoso o defraudar expectativas, dicho de cosas impersonales', 'Fallar, resultar engañoso o defraudar expectativas, dicho de cosas impersonales. La cosecha de aceitunas ''falla'' (Hab 3:17) y la era ''miente'' al pueblo (Os 9:2): promesas de cosecha que quedan incumplidas. Esta extensión metafórica personifica la naturaleza como testigo poco fiable, usando el mismo vocabulario de engaño aplicado al habla humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105923, 'spa', 'Enflaquecer, adelgazar o consumirse físicamente', 'Enflaquecer, adelgazar o consumirse físicamente. Esta única ocurrencia en Qal aparece en el Salmo 109:24: ''mi carne enflaqueció, sin gordura'', describiendo el deterioro corporal bajo la aflicción. El cognado arameo confirma este como el sentido más concreto y físico de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105924, 'spa', 'Mentira, engaño', 'Mentira, engaño o traición como categoría moral — falsedad que corrompe la fidelidad al pacto. Cinco apariciones, mayormente en Oseas: ''habéis arado maldad, habéis segado mentira'' (Os 10:13); sus líderes se deleitan en ''sus mentiras'' (Os 7:3); Efraín ''me rodea de mentira'' (Os 11:12). Nahúm 3:1 aplica el término a Nínive.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105928, 'spa', 'Flaqueza, demacración', 'Delgadez física, emaciación o deterioro del cuerpo — sentido genuinamente distinto del moral. Se encuentra únicamente en Job 16:8, donde Job lamenta que ''mi flaqueza se ha levantado contra mí y testifica en mi rostro'', describiendo su cuerpo devastado como testigo de aflicción. El cognado targúmico kachsha confirma la lectura física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105931, 'spa', 'Causal: porque, pues', 'Conjunción causal: ''porque, pues'' — introduce la razón de lo que precede. Sentido dominante en cerca de 3.500 ocurrencias. Gn 3:10 muestra a Adán explicando ''porque tuve miedo''. La partícula vertebra la arquitectura argumentativa del hebreo bíblico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105933, 'spa', 'Declarativa: que', 'Completiva declarativa: ''que'' — introduce cláusulas de contenido tras verbos de percepción, habla o conocimiento. Gn 1:4 inaugura este uso: ''vio Dios que era bueno''. Es el segundo empleo más frecuente y funciona como bisagra sintáctica entre un verbo mental y su objeto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105938, 'spa', 'Temporal: cuando', 'Conjunción temporal: ''cuando'' — señala el momento en que algo ocurre. Gn 6:1 abre con ''cuando los hombres comenzaron a multiplicarse''. El paso de lo causal a lo temporal es natural: causa y ocasión comparten una estructura lógica común.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105944, 'spa', 'Adversativa: sino, más bien', 'Conjunción adversativa: ''sino, más bien'' — marca contraste o corrección. Gn 42:12 presenta a José insistiendo: ''No, sino que habéis venido a ver la desnudez de la tierra''. 1 S 8:7 revela: ''no te han desechado a ti, sino a mí''. Transmite fuerza correctiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105949, 'spa', 'Condicional: si, cuando', 'Conjunción condicional: ''si, cuando'' — introduce cláusulas contingentes en formulaciones legales casuísticas. Éx 21:2 (''si comprares un siervo hebreo'') y 21:33 (''si alguno abriere un pozo'') enmarcan la ley de casos. Refleja la superposición condicional-temporal propia del derecho antiguo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105955, 'spa', 'Aseverativa: ciertamente', 'Partícula aseverativa: ''ciertamente, en verdad'' — afirma enfáticamente una verdad. Dt 30:14 declara ''ciertamente muy cerca de ti está la palabra''. Jos 2:24 informa: ''ciertamente el SEÑOR ha entregado toda la tierra''. No subordina, sino que afirma con vigor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105959, 'spa', 'Concesiva: aunque', 'Conjunción concesiva: ''aunque, aun cuando'' — reconoce una circunstancia a pesar de la cual la cláusula principal se mantiene. Sal 37:24 promete: ''aunque caiga, no quedará postrado''. El uso concesivo es infrecuente pero teológicamente denso, sosteniendo en tensión el sufrimiento y la confianza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105969, 'spa', 'Porque, pues (causal)', 'Uso causal (~37 veces) que ofrece la razón o fundamento de lo anterior, a menudo introduciendo una prótasis condicional. Las narraciones de las plagas de Éxodo lo emplean repetidamente (Ex 8:21; 9:2; 10:4): ''porque si rehúsas dejar ir a mi pueblo…'', donde כִּי conserva su fuerza causal mientras אִם añade el elemento condicional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105970, 'spa', 'Sino, más bien (adversativa)', 'Uso adversativo ''sino, más bien'': el más frecuente (~57 veces), normalmente tras una negación para introducir la verdad contrastante. En Gn 32:28 se dice a Jacob que su nombre ya no será Jacob כִּי אִם Israel; en Dt 7:5 se ordena a Israel no hacer pactos sino derribar los altares. El patrón ''no X כִּי אִם Y'' es la estructura típica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105972, 'spa', 'Excepto, a menos que', 'Uso exceptivo (~48 veces) que restringe una afirmación general para señalar una excepción. Gn 39:9 es paradigmático: Potifar ha puesto todo en manos de José excepto (כִּי אִם) a su esposa. En Gn 32:26 Jacob no soltará al ángel a menos que reciba una bendición. El francés sauf y el alemán ausser traducen esta acepción de forma distinta a la adversativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105977, 'spa', 'Ciertamente, que (aseverativa)', 'Uso aseverativo o de cláusula sustantiva (~6 veces), el más raro, que aparece en fórmulas de juramento y declaraciones solemnes. En 1 S 14:39 Saúl jura כִּי אִם (''ciertamente'') Jonatán morirá; en Jr 26:15 Jeremías declara כִּי אִם (''verdaderamente/que'') estáis trayendo sangre inocente sobre vosotros. El español ciertamente y el alemán dass captan respectivamente los polos enfático y completivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105994, 'spa', 'Porque, por cuanto', 'Conjunción causal compuesta kî ʿal kēn, literalmente ''porque por tanto'', que duplica pleonásticamente la fuerza causal para enfatizar el motivo de una acción. Se encuentra en discurso narrativo elevado en Génesis, Números, Jueces, Samuel y Jeremías (Gn 18:5; 19:8; 33:10; 38:26; Nm 10:31; 14:43). Abraham la usa para explicar por qué los viajeros han pasado por su camino; Moisés la emplea para persuadir a Hobab.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106000, 'spa', 'Jabalina, lanza arrojadiza', 'Sustantivo masculino que designa una lanza ligera arrojadiza o jabalina, distinta de la חֲנִית (lanza pesada de acometida). En el relato de David y Goliat, la jabalina de bronce del gigante colgaba entre sus hombros como parte de su triple armamento: espada, lanza y jabalina (1 Sam 17:6, 45). La jabalina de Josué funcionó como señal táctica: «Extiende hacia Hai la jabalina que tienes en la mano» (Jos 8:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106008, 'spa', 'Una fuente o pila de bronce utilizada para la purificación sacerdotal, el recipi', 'Una fuente o pila de bronce utilizada para la purificación sacerdotal, el recipiente de lavamiento ritual situado ante el tabernáculo y multiplicado después en el templo de Salomón. Éxodo 30:18 hasta 1 Reyes 7:38-43 establecen su papel litúrgico central como parte del mobiliario sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106013, 'spa', 'Una olla, caldero o brasero usado en contextos domésticos o figurados', 'Una olla, caldero o brasero usado en contextos domésticos o figurados. En 1 Samuel 2:14 aparece entre utensilios de cocina comunes (junto a la caldera y la sartén), mientras que Zacarías 12:6 lo emplea metafóricamente como un brasero de fuego entre leños, representando a los jefes de Judá consumiendo a sus enemigos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106016, 'spa', 'Una plataforma o estrado elevado de bronce, atestiguado en 2 Crónicas 6', 'Una plataforma o estrado elevado de bronce, atestiguado en 2 Crónicas 6:13 donde Salomón se arrodilla sobre una estructura de bronce especialmente construida en el atrio del templo. Este sentido extiende la forma de recipiente de bronce hacia un elemento arquitectónico para posicionamiento ceremonial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106021, 'spa', 'Cúmulo estelar', 'Las Pléyades aparecen en tres pasajes poéticos que celebran la majestad creadora de Dios. Job 9:9 las enumera junto a la Osa, Orión y las cámaras del sur; Job 38:31 habla de sus «cadenas» o «ligaduras» (מַעֲדַנּוֹת); Amós 5:8 las empareja con Orión al alabar al Creador. Las traducciones tienden a conservar la forma reconocible «Pléyades», reflejando la universalidad de este nombre estelar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106022, 'spa', 'Bolsa, bolsillo', 'Bolsa de cuero para llevar dinero o pesas comerciales. Con pesas, aparece en contextos legales contra el comercio deshonesto: ''No tendrás en tu bolsa pesa grande y pesa chica'' (Dt 25:13), y ''bolsa de pesas engañosas'' (Mi 6:11). Con dinero, funciona como monedero: la bolsa compartida en Proverbios 1:14, y el oro para fabricar ídolos en Isaías 46:6.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106030, 'spa', 'Asi, de esta manera', 'Asi, de esta manera. Adverbio demostrativo que especifica modo, con significado de ''asi, de este modo, de esta manera'', usado para senalar hacia adelante una instruccion o hacia atras una accion descrita. Se asocia frecuentemente con עָשָׂה (''hacer'') en los actos simbolicos profeticos: el entierro del cinturon de Jeremias ilustra ''asi arruinare el orgullo de Juda'' (Jer 13:9), y su rollo hundido representa ''asi se hundira Babilonia'' (Jer 51:64). En narrativa, introduce preguntas retoricas que indagan sobre un estado o accion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106036, 'spa', 'Talento (unidad de peso) — Un talento, la unidad de peso estándar más grande del', 'Talento (unidad de peso) — Un talento, la unidad de peso estándar más grande del sistema bíblico, de aproximadamente 30-34 kilogramos. Se emplea extensamente en los relatos de la construcción del templo (Éx 25:39; 38:24-27), tributos reales y transacciones comerciales. En español «talento», en francés «talent» y en alemán «Talent» toman prestada la misma palabra grecolatina que a su vez deriva de este patrón de peso semítico. La forma dual (dos talentos) y las cifras elevadas reflejan el alcance de los proyectos de construcción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106040, 'spa', 'Llanura o región del valle — Un distrito geográfico llano y redondo, más caracte', 'Llanura o región del valle — Un distrito geográfico llano y redondo, más característicamente el valle del Jordán visto desde arriba como una cuenca circular y baja. La frase כִּכַּר הַיַּרְדֵּן (la llanura del Jordán) domina este sentido y aparece en la narración de Lot (Gn 13:10-12) y en el relato de la destrucción de Sodoma (Gn 19:17, 25). En español «llanura», en francés «plaine» y en alemán «Ebene» traducen el referente geográfico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106043, 'spa', 'Hogaza o torta redonda — Una hogaza, disco o torta redonda de pan o alimento sim', 'Hogaza o torta redonda — Una hogaza, disco o torta redonda de pan o alimento similar. La conexión de forma con la ''redondez'' es aquí más transparente. Gedeón solicita panes para sus tropas agotadas (Jue 8:5), Samuel anuncia a Saúl que recibirá tres panes como señal profética (1 Sam 10:3), y se reparte una hogaza en la celebración del arca (1 Cr 16:3). En español «hogaza» o «torta» distinguen claramente este sentido del peso y la geografía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106067, 'spa', 'todo, todos, toda', 'Cuantificador atributivo que modifica un sustantivo para expresar totalidad o universalidad: ''todo el pueblo'', ''toda nación'', ''toda la tierra''. Este sentido abrumadoramente dominante (5.352 ocurrencias) aparece desde Génesis hasta Malaquías, abarcando personas, territorios, tiempo y la creación entera (Gn 11:9; 18:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106106, 'spa', 'todo, la totalidad', 'Uso sustantivado o absoluto donde כֹּל funciona como sustantivo significando ''todo'', ''la totalidad'' o ''todas las cosas'', frecuentemente con artículo o en contextos filosóficos. Eclesiastés emplea este sentido repetidamente: ''todo es vanidad'' (Ecl 1:2), ''vi todas las obras'' (Ecl 1:14), pasando de modificador a la cosa misma que modifica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106111, 'spa', 'todos vosotros (pronominal)', 'Uso con sufijos pronominales para expresar la totalidad de un grupo referido: ''todos vosotros'', ''todos ellos'', ''toda ella''. Dt 29:10 reúne a ''todos vosotros'' ante el Señor, y Cnt 4:7 declara ''toda tú eres hermosa''. La construcción conserva una cualidad personal y envolvente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106124, 'spa', 'cualquier, ninguno', 'Sentido indefinido empleado especialmente en contextos negativos, condicionales o interrogativos: ''cualquier'', ''alguno'', ''ninguno''. Deuteronomio 4:15-18 repite el patrón ''cualquier forma'', ''cualquier semejanza'', ''cualquier figura'', donde כֹּל no suma una totalidad sino que explora posibilidades, pasando de la cuantificación universal a la indefinida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106147, 'spa', 'cada uno (distributivo)', 'Sentido distributivo que enfatiza los miembros individuales de una clase en lugar del grupo como conjunto: ''para cada cosa'', ''cada uno''. Eclesiastés 3:1 declara célebremente ''para todo hay un tiempo'', distribuyendo entre cada elemento. Este matiz de uno por uno se distingue de la totalidad colectiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106171, 'spa', 'Todo, cada, entero', 'Totalidad aplicada a un grupo o clase definidos: ''todos los sabios'', ''todo el reino'' (Dn 6:2-4). Es el uso más frecuente (70 veces), en estado constructo con un sustantivo plural para indicar cada miembro del conjunto especificado. Predomina en las fórmulas de decretos reales de Daniel y en el lenguaje administrativo de Esdras (p. ej., Esd 7:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106172, 'spa', 'Cualquier, cualquiera', 'Uso indefinido o distributivo con el sentido de ''cualquier, cualquiera que, lo que sea'', frecuente en contextos condicionales, negativos o generalizadores. En Esd 6:11-12 el decreto amenaza a ''cualquier hombre'' que altere el edicto y a ''cualquier rey o pueblo'' que se oponga al templo. Dn 6:8 habla de una petición a ''cualquier dios''. Esta acepción (28 veces) pasa de la totalidad colectiva a la distribución abierta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106181, 'spa', 'Todo, la totalidad', 'Uso sustantivado en estado enfático/determinado (כֹּלָּא) con el sentido de ''todo, todas las cosas, la totalidad'', funcionando como sustantivo independiente y no como modificador. Dn 2:40 habla del hierro que ''quebranta y desmenuza todo'' (כֹּלָּא); Dn 4:12 describe el árbol que alimentaba a ''todos''. Cinco apariciones llevan este peso, donde la palabra misma es sujeto u objeto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106188, 'spa', 'Contener, retener, impedir', 'Contener, retener, impedir: el sentido activo principal en Qal: contener, retener o impedir que alguien o algo proceda o sea dado. Abraham pide que nadie le niegue un lugar de sepultura (Gn 23:6); Abigail contuvo a David del derramamiento de sangre (1 S 25:33); el salmista declara que no retuvo sus labios de proclamar la justicia (Sal 40:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106190, 'spa', 'Ser detenido, cesar', 'Ser detenido, cesar: el sentido pasivo Nifal: ser detenido, retenido o hecho cesar. Las fuentes del abismo y las ventanas del cielo fueron ''detenidas'' tras el diluvio (Gn 8:2); se ordenó al pueblo dejar de traer ofrendas porque había más que suficiente (Éx 36:6); Dios retiene las aguas en Ez 31:15.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106191, 'spa', 'Confinar, encerrar, encarcelar', 'Confinar, encerrar, encarcelar: el sentido de confinamiento físico o encarcelamiento: encerrar o enclaustrar a alguien en un espacio. Jeremías es confinado en el patio de la guardia (Jer 32:2-3) y el salmista lamenta estar encerrado sin escapatoria (Sal 88:8). Los filisteos encerraron a sus vacas lecheras (1 S 6:10) en un corral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106204, 'spa', 'Llevar a su fin, concluir', 'Llevar a su fin, concluir: el sentido intensivo Piel que aparece solo en Dn 9:24: llevar a término, concluir o sellar la transgresión. Las setenta semanas están decretadas ''para terminar'' la transgresión y sellar el pecado. Esto extiende la metáfora radical de contención hasta su conclusión definitiva: no solo retener, sino llevar algo a su fin señalado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106205, 'spa', 'Prisión, encierro', 'Sustantivo masculino que significa encierro, reclusión o encarcelamiento, mayormente en la construcción bêth (hak)keleʾ (''casa de prisión'', 1 R 22:27; 2 Cr 18:26; 2 R 17:4; Jer 37:15, 18). También aparece en la expresión bigdê kilʾô (''vestiduras de su prisión'', 2 R 25:29 = Jer 52:33), referida a ropa carcelaria. El plural de Isaías bāttê kelāʾîm (42:22) extiende la imagen metafóricamente a Israel atrapado en cautividad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106212, 'spa', 'Mezcla prohibida', 'El término aparece cuatro veces en leyes contra la mezcla de especies. Levítico prohíbe cruzar «dos especies» de ganado, sembrar campos con «semillas mezcladas» y vestir prendas de «especies mezcladas» de tela (Lv 19:19). Deuteronomio igualmente prohíbe sembrar viñedos con «semillas mezcladas» para que la cosecha no quede consagrada (Dt 22:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106213, 'spa', 'Perro (animal)', 'Perro (animal). El perro domestico, visto principalmente como carronero y animal culturalmente despreciado. Las referencias literales describen perros feroces y hambrientos devorando cadaveres y lamiendo sangre en los oraculos de juicio deuteronomistas (1 R 14:11; 21:19; 2 R 9:10, 36). Figuradamente, ''perro muerto'' expresa la maxima autodenigracion (1 S 24:14; 2 S 9:8). Job 30:1 menciona el unico perro de trabajo — el perro pastor — e incluso alli implica bajeza. Dt 23:18 prohibe traer el ''precio de un perro'' al templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106227, 'spa', 'Caleb (lider israelita)', 'Caleb (lider israelita). Nombre propio Kalev (Caleb), que identifica al hijo de Jefune el cenezeo quien, junto con Josue, trajo un informe fiel tras explorar Canaan y fue recompensado con la promesa de Hebron. La frase ''siguio plenamente al SENOR'' (Nm 14:24; 32:12; Dt 1:36; Jos 14:8-9, 14) funciona como epiteto formulaico. Las apariciones narrativas se concentran en Numeros 13-14 (el episodio de los espias) y Josue 14-15 (la reclamacion de la herencia).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106234, 'spa', 'Completar una tarea (Piel)', 'Acepción transitiva Piel nuclear de llevar una tarea o proyecto definido a su conclusión prevista: construir una casa, concluir un discurso, completar un viaje. El árabe akmala, el coreano 마쳤다 y el suajili -maliza distinguen consistentemente esta culminación deliberada de la mera cesación, reflejando el énfasis bíblico en la obra terminada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106236, 'spa', 'Llegar a su fin (Qal)', 'Acepción intransitiva Qal donde procesos o provisiones alcanzan su punto final natural sin que un agente los termine activamente. El agua del odre se acaba (Gn 21:15), los siete años de abundancia terminan (Gn 41:53), la construcción del templo se completa (Ex 39:32). El coreano 끝났다 (''terminó'') y el árabe intahā (''concluyó'') captan la cualidad pasiva e inevitable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106240, 'spa', 'Desfallecer, languidecer (Qal)', 'Uso Qal conmovedor que describe el debilitamiento de las facultades humanas bajo la tensión: ojos que se nublan de llanto (Sal 31:10; Job 17:5), alma que desfallece de anhelo (Sal 119:81), fuerza que se consume bajo la reprensión divina (Sal 39:10). El árabe kallat y el coreano 쇠하다 denotan debilitamiento, no simple cesación, en consonancia con el registro emocional de estos salmos de lamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106242, 'spa', 'Ser determinado, decretado (Qal)', 'Uso Qal especializado en contextos narrativos donde un curso de acción o destino queda resuelto, determinado o decretado como definitivo: Jonatán advirtiendo a David que el mal de Saúl está determinado (1 S 20:7, 9), Ester reconociendo que la perdición de Amán está sellada (Est 7:7). El árabe quḍiyat (''fue juzgado'') subraya la finalidad judicial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106245, 'spa', 'Consumir, destruir (Piel)', 'Uso Piel intensificado donde la culminación se convierte en aniquilación total: Dios amenazando con consumir a Israel en el desierto (Ex 32), el hambre consumiendo una tierra (Gn 41). No se trata de simplemente acabar sino de destruir por completo: el árabe afnā (''destruir totalmente''), el coreano 멸하다 (''exterminar''). El paso de ''terminar'' a ''acabar con'' refleja la intensidad inherente del Piel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106248, 'spa', 'Gastar, agotar (Piel)', 'Acepción Piel centrada en gastar o consumir recursos, distinta de destruir enemigos: David gastando su fuerza en vano (Is 49:4), Moisés advirtiendo sobre consumir los días bajo la ira de Dios (Sal 90:9), flechas disparadas hasta agotarlas. Las traducciones reflejan el agotamiento de recursos (árabe atimmu, coreano 소모하다), diferenciándose de la aniquilación de la acepción 2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106280, 'spa', 'Ser completado (Pual)', 'Forma pasiva Pual que indica que una obra o creación ha sido llevada a su culminación por un agente externo. Gn 2:1 declara que los cielos y la tierra ''fueron acabados'' por los actos creativos de Dios; Sal 72:20 marca la conclusión de las oraciones de David. El coreano 완성되었다 (''fue completado'') y el árabe uktumilat (''fue hecho completo'') captan el ser terminado por la acción de otro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106285, 'spa', 'Anhelar o cesar', 'Aparición incierta en 2 S 13:39 donde el espíritu de David se describe con una forma verbal que podría significar ''anheló'' o ''cesó''. La ambigüedad textual y semántica divide a los traductores entre el anhelo por Absalón y el cese de perseguirlo. Los glosarios multilingües revelan la tensión interpretativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106331, 'spa', 'Consumir (juicio)', 'Aparición aislada y difícil en Is 27:10, donde el contexto de juicio sobre una ciudad fortificada emplea una forma que puede significar ''consumir'' o ''destruir'', en paralelismo con ganado que pasta y arranca ramas. La evidencia de las traducciones muestra incertidumbre sobre si se trata de consumo o de culminación dentro del oráculo de juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106346, 'spa', 'Cumplir, realizar (Qal)', 'Acepción intransitiva Qal que subraya el cumplimiento teleológico: propósitos, profecías o planes divinos que alcanzan su fruición señalada. Se usa del templo de Salomón terminado en todos sus detalles (1 R 6:38), del decreto de Ciro cumpliendo la profecía de Jeremías sobre setenta años (2 Cr 36:22; Esd 1:1). Los glosarios multilingües destacan la realización con propósito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106360, 'spa', 'Destrucción (apocalíptica)', 'Aparición aislada en Dn 11:16 donde el rey invasor actúa con poder destructivo en la ''tierra gloriosa''. La forma parece indicar destrucción o aniquilación como parte de la narrativa de conquista, aunque el matiz preciso en este contexto apocalíptico permanece algo incierto en las tradiciones de traducción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106395, 'spa', 'El sentido principal denota destrucción completa o aniquilación, casi siempre co', 'El sentido principal denota destrucción completa o aniquilación, casi siempre como acto de juicio divino. Los profetas lo combinan con palabras de exterminio y decreto (Is 10:23; Nah 1:8-9) para subrayar una ruina total e irreversible. Cuando los profetas dicen que Dios hará una כָּלָה, se refieren a una devastación exhaustiva y definitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106398, 'spa', 'Usado adverbialmente para significar ''completamente'' o ''del todo'', modificando l', 'Usado adverbialmente para significar ''completamente'' o ''del todo'', modificando la totalidad de una acción en vez de nombrar la destrucción en sí. En Génesis 18:21 Dios desciende a ver si el clamor contra Sodoma es ''del todo'' como se ha reportado, y en Éxodo 11:1 la palabra intensifica la finalidad de la expulsión de Israel por parte de Faraón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106401, 'spa', 'Un sentido especializado que apunta a un decreto determinado o un propósito divi', 'Un sentido especializado que apunta a un decreto determinado o un propósito divino resuelto. En 1 Samuel 20:33, Jonatán percibe que su padre Saúl había ''determinado'' matar a David; el énfasis recae no en el acto de destrucción sino en la decisión irrevocable detrás de él. Daniel 9:27 emplea una forma relacionada en el mismo sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106407, 'spa', 'Novia', 'Novia. Novia — mujer en su boda o en contexto de celebracion nupcial, usada tanto literalmente como en poderosa metafora teologica. El Cantar de los Cantares se dirige a la amada como kallah seis veces (4:8-12; 5:1), y los profetas emplean la imagen de una novia que se adorna para representar la restauracion de Sion (Is 49:18; 61:10; 62:5). La frase recurrente de Jeremias ''la voz del esposo y la voz de la esposa'' simboliza la alegria que enmudecera bajo el juicio (Jer 7:34; 25:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106409, 'spa', 'Nuera', 'Nuera. Nuera — la esposa de un hijo en relacion con sus suegros. El sentido familiar primario aparece a lo largo de la Tora y la narrativa de Rut: Tamar como kallah de Juda (Gn 38:11, 16, 24), las prohibiciones leviticas contra descubrir a la nuera (Lv 18:15; 20:12), y sobre todo la relacion devota de Rut con Noemi (Rt 1:6-8, 22; 2:20, 22; 4:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106427, 'spa', 'Jaula o canasta', 'Jeremías 5:27 emplea el símil de una jaula (כְּלוּב) llena de aves para describir casas colmadas de traición. Amós 8:1-2 presenta la visión de una canasta de fruta de verano (קַיִץ), con un juego de palabras sobre קֵץ (fin). En el contexto de Jeremías predomina la traducción «jaula», mientras que en Amós prevalece «canasta». Esta doble capacidad del término —contener criaturas vivas o frutos cosechados— enriquece su fuerza retórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106435, 'spa', 'Vasija o recipiente', 'La acepción nuclear y más frecuente (206 veces): un receptáculo o contenedor — olla, jarro, cuenco, tinaja o vasija sagrada. El árabe إناء/أنية se corresponde directamente. Los inventarios del tabernáculo (Ex 27:19; 38:3, 30) representan una gran parte, y la vasija del alfarero de Jr 18:4 se convirtió en poderosa metáfora profética de la soberanía divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106438, 'spa', 'Arma o armadura', 'Armas y armadura (59 veces): implementos de guerra que incluyen espadas, lanzas, arcos y equipo defensivo. El árabe سلاح y el suajili silaha captan este registro militar. Los ''instrumentos de violencia'' de Simeón y Leví (Gn 49:5) constituyen la primera atestación; la frase כְּלֵי מִלְחָמָה (''armas de guerra'') se vuelve formularia en Deuteronomio y los libros históricos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106442, 'spa', 'Instrumento musical', 'Instrumentos musicales (14 veces): dispositivos para la música litúrgica — arpas, liras, címbalos, trompetas. El árabe آلة (en contexto musical), el coreano 악기 y el hindi वाद्य emplean terminología instrumental específica donde el hebreo usa כְּלִי más un genitivo de tipo. Esta acepción se concentra casi enteramente en los pasajes de música del templo en Crónicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106445, 'spa', 'Artículo u objeto', 'Artículo u objeto en general (21 veces): uso abstracto para cualquier cosa sin mayor especificación. La construcción כְּלֵי כֶסֶף וּכְלֵי זָהָב (''objetos de plata y objetos de oro'', Gn 24:53; Ex 3:22; 11:2) reaparece en contextos de obsequios y del despojo del Éxodo, donde la palabra funciona como clasificador casi genérico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106463, 'spa', 'Enseres o equipaje', 'Bienes, equipaje o pertenencias personales (22 veces): propiedad portátil que se lleva en viajes o se guarda en hogares. El árabe أمتعة/متاع y el coreano 짐/물건 reflejan el campo semántico. La búsqueda de Labán entre los ''bienes'' de Jacob (Gn 31:37) y el botín robado escondido entre los כֵּלִים de Israel (Jos 7:11) ejemplifican las posesiones en contextos de tensión narrativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106514, 'spa', 'Joyas, adornos', 'Joyas o atavíos ornamentales (1 vez, Is 61:10): una novia que se adorna con sus כֵּלִים, traducidos como ''joyas''. Esta extensión metafórica — de objeto fabricado a adorno personal — encaja con la lógica semántica más amplia de כְּלִי como cualquier cosa forjada con destreza, aplicada aquí al gozo escatológico de Sion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106537, 'spa', 'Bolsa o morral', 'Bolsa o morral (2 veces): un pequeño contenedor flexible para llevar piedras o provisiones. El árabe كيس y el suajili mfuko especifican esta acepción más restringida. Ambas apariciones surgen en el relato de David y Goliat: el morral de pastor del que David escogió cinco piedras lisas (1 S 17:40, 49).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106558, 'spa', 'Prisión real', 'El término aparece dos veces en Jeremías con variación Ketiv-Qere. Jeremías 37:4 señala que «Jeremías aún no había sido puesto en la prisión», usando ambas lecturas para designar el lugar de encierro. Jeremías 52:31 describe cómo el rey de Babilonia sacó a Joaquín «de la prisión» y le mostró favor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106559, 'spa', 'Rinones (organo anatomico)', 'Rinones (organo anatomico). Los rinones fisicos como organo interno, especialmente en el contexto del sacrificio animal donde se extraen con su grasa y se ofrecen sobre el altar. Predominante en 22 apariciones, concentradas en la legislacion sacerdotal de Exodo y Levitico. Los rinones aparecen junto con la grasa de las entranas como la porcion mas selecta ofrecida a Dios (Ex 29:13; Lv 3:4, 10, 15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106560, 'spa', 'Ser intimo, conciencia', 'Ser intimo, conciencia. El ser mas intimo, la conciencia o la sede mas profunda de las emociones, donde los rinones sirven como metafora de la vida interior oculta que Dios examina e instruye. Presente en 9 pasajes poeticos y profeticos. Dios prueba los rinones y el corazon juntos como merismo de toda la persona interior (Sal 7:9; Jer 11:20; 17:10). Los rinones del salmista le instruyen de noche (Sal 16:7), y las flechas de Dios los traspasan como sede del sufrimiento mas intimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106570, 'spa', 'Nombre propio', 'Quilión aparece en momentos clave de la narrativa de Rut: es presentado en 1:2 como hijo de Noemí, se reporta su muerte en 1:5 tras diez años en Moab, y se lo menciona nuevamente en 4:9 cuando Booz redime legalmente la herencia familiar. Su nombre posiblemente derive de una raíz que implica «consumición», prefigurando su muerte prematura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106572, 'spa', 'Completitud cuantitativa', 'Completitud cuantitativa: ''entero, enteramente, la totalidad de'', funcionando como adjetivo o acusativo adverbial que indica totalidad. El manto del efod es כָּלִיל de azul, ''enteramente de azul'' (Éx 28:31; 39:22), y en Jueces 20:40, ''toda la ciudad'' asciende en humo. El español ''completamente'' y el alemán ''ganz-von'' convergen en la lectura cuantitativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106574, 'spa', 'Perfección cualitativa', 'Perfección cualitativa: ''perfecto, sin defecto, completo en hermosura''. Concentrado en Ezequiel y Lamentaciones — la belleza de Jerusalén es ''perfecta'' por el esplendor divino (Ez 16:14), Tiro es כְּלִילַת יֹפִי, ''perfección de hermosura'' (Ez 27:3; 28:12), y se lamenta a Jerusalén como otrora ''perfección de hermosura'' (Lam 2:15). El español ''perfecta'' y la forma constructa distintiva כְּלִילַת señalan una lectura cualitativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106575, 'spa', 'Holocausto u ofrenda quemada completa — un sacrificio enteramente consumido por ', 'Holocausto u ofrenda quemada completa — un sacrificio enteramente consumido por el fuego sin reservar porción alguna. Los levitas ''pondrán holocausto sobre tu altar'' (Dt 33:10), Samuel ofrece un cordero como כָּלִיל (1 Sam 7:9), y el salmista promete que Dios se deleitará en ofrendas completas (Sal 51:19). El español ''holocausto'' despliega vocabulario sacrificial especializado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106586, 'spa', 'Completar, terminar', 'Completar o terminar un proyecto de construcción, atestiguado solo en las secciones arameas de Esdras sobre la reconstrucción del templo y los muros de Jerusalén. En forma activa Shaf''el: ''lo terminaron'' (Esd 5:11; 6:14) y ''completaron los muros'' (Esd 4:12); en Ishtaf''el pasivo: ''los muros serán completados'' (Esd 4:13, 16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106593, 'spa', 'avergonzarse, ser deshonrado (Nifal)', 'avergonzarse, ser deshonrado (Nifal): experimentar vergüenza o deshonra pública como estado interior. Números 12:14 establece el paradigma: una vergüenza que perdura y aísla. En Isaías 45:16-17 los idólatras «son avergonzados» mientras Israel «no será avergonzado», enmarcando la vergüenza como antítesis de la salvación. Esdras 9:6 interioriza la vergüenza como penitencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106594, 'spa', 'humillar, avergonzar (Hifil)', 'humillar, avergonzar (Hifil): causar activamente vergüenza a otra persona. Jueces 18:7 describe una ciudad sin nadie que «los avergonzara»; Rut 2:15 ordena a los segadores no «humillar» a la espigadora; 1 Samuel 20:34 registra la ira de Jonatán porque Saúl había «deshonrado» a David.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106596, 'spa', 'ser humillado por otro (Hofal)', 'ser humillado por otro (Hofal): la voz pasiva del Hifil, ser causado vergüenza por un agente externo. Solo tres ocurrencias distinguen este sentido del Nifal al enfatizar que la deshonra fue infligida. En 1 Samuel 25:15 los siervos reportan que no «fueron avergonzados»; Jeremías 14:3 retrata a los nobles «avergonzados» por la sequía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106630, 'spa', 'El estado subjetivo o condición de vergüenza e ignominia, a menudo como consecue', 'El estado subjetivo o condición de vergüenza e ignominia, a menudo como consecuencia del pecado, la derrota o el juicio divino. El salmista ora para que sus enemigos sean ''revestidos de vergüenza'' (Sal 109:29), e Isaías advierte que los fabricantes de ídolos ''irán a la ignominia'' juntos (Is 45:16). Frecuentemente emparejado con בֹּשֶׁת en las denuncias proféticas (Is 30:3; 61:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106633, 'spa', 'Deshonra pública, descrédito o reproche experimentado como consecuencia social', 'Deshonra pública, descrédito o reproche experimentado como consecuencia social: la dimensión externa de la humillación infligida por otros o reconocida por la comunidad. El salmista lamenta ''mi deshonra está continuamente delante de mí'' (Sal 44:15), y Jeremías describe la vergüenza de Israel como algo que ''nos cubre'' (Jer 3:25). En el Salmo 69:19, el sufriente apela a Dios que conoce su reproche y deshonra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106637, 'spa', 'Actos concretos o instancias de insulto y humillación, usados en plural para den', 'Actos concretos o instancias de insulto y humillación, usados en plural para denotar afrentas repetidas. En Isaías 50:6, el Siervo sufriente testifica: ''no escondí mi rostro de las injurias y los escupitajos'', donde el plural כְּלִמּוֹת señala actos específicos y reiterados de degradación, no un estado general. Esta profecía anticipada del sufrimiento del Siervo le confiere al término su forma más visceral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106654, 'spa', 'Nombre propio y topónimo', 'Nombre propio masculino que identifica a un servidor de David vinculado con Barzilai el galaadita, y por extensión un lugar cerca de Belén que lleva su nombre. En 2 Samuel 19:37-40 acompaña a David cruzando el Jordán; en Jeremías 41:17 el topónimo Gerut Quimam preserva su legado como terrateniente cerca de Belén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106655, 'spa', 'Como (comparación)', 'Acepción comparativa dominante: ''como, a semejanza de'', estableciendo un símil o analogía entre dos cosas. Presente 139 veces con sufijos pronominales y en versos poéticos, es la función estándar de כְּמוֹ en todo su rango. En Ex 15:5 los egipcios se hunden ''como una piedra'' (כְּמוֹ אָבֶן); en Job 6:15 los hermanos de Job son infieles ''como un torrente'' que se seca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106669, 'spa', 'Y como (comparación conjunta)', 'Comparación conjunta con la conjunción waw prefijada: ''y como, y a semejanza de''. Solo 2 apariciones (Gn 19:15 e Is 41:25), ambas enlazando una cláusula comparativa con lo precedente. En Gn 19:15 la frase marca el momento ''cuando subió el alba''; en Is 41:25 el conquistador viene sobre los gobernantes ''y como alfarero pisa el barro''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106671, 'spa', 'Así, de este modo', 'Uso adverbial con el sentido de ''así, de este modo'', sin un objeto directo de comparación. Atestiguado una vez en Sal 73:15, donde el salmista dice ''si hubiera hablado así (כְּמוֹ), habría traicionado a la generación de tus hijos''. Aquí כְּמוֹ apunta hacia atrás, al pensamiento precedente, en lugar de hacia adelante a un objeto comparado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106679, 'spa', 'Quemos', 'Nombre propio de la deidad principal de los moabitas, que aparece en contextos de santuarios idolátricos y juicio profético. Números 21:29 identifica a Moab como «pueblo de Quemos», y Jueces 11:24 podría extender su culto a los amonitas, aunque probablemente se trate de una confusión textual. Todas las apariciones subrayan la condena bíblica de la idolatría moabita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106686, 'spa', 'Especia aromática', 'Las tres apariciones se concentran en Isaías 28:25, 27 (×2), donde el profeta contrasta el comino con el trigo y la cebada para demostrar la sabiduría proporcionada tanto en la agricultura como en el juicio divino. Las delicadas semillas requieren una trilla suave —una vara o bastón, no una rueda de carro—, reflejando el cuidado de Dios al disciplinar a su pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106688, 'spa', 'Compasión encendida', 'El verbo Nifal describe tanto la agitación emocional como el calor físico. La compasión de José «se enternece hacia su hermano» al ver a Benjamín, obligándolo a retirarse y llorar (Gn 43:30). La compasión de la verdadera madre «se conmovió por su hijo» cuando Salomón amenazó con dividir al niño (1 R 3:26). Oseas retrata la declaración de Dios: «Mis compasiones se encienden juntas» al debatir si destruir a Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106689, 'spa', 'Sacerdote pagano', 'Las tres apariciones bíblicas marcan momentos de crisis religiosa y reforma. En 2 Reyes 23:5, Josías purga a los כֹּמָרִים nombrados por los reyes de Judá para el culto astral y a Baal. Oseas 10:5 lamenta que incluso los sacerdotes idólatras del becerro gemirán por su exilio. Sofonías 1:4 profetiza su eliminación total junto con los vestigios de Baal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106692, 'spa', 'Honrado, íntegro y digno de confianza en carácter, aplicado exclusivamente a per', 'Honrado, íntegro y digno de confianza en carácter, aplicado exclusivamente a personas. Este sentido se concentra en la narrativa de José en Génesis 42:11, 19, 31, 33, 34, donde los hermanos insisten en que son כֵּנִים — hombres honrados, no espías. El peso moral va más allá de la simple corrección factual hacia la integridad personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106693, 'spa', 'Correcto, recto, apropiado o adecuado, dicho de discursos, acciones o estados de', 'Correcto, recto, apropiado o adecuado, dicho de discursos, acciones o estados de cosas que son exactos o pertinentes. Moisés confirma la declaración de Faraón como ''correcta'' en Éxodo 10:29, y Dios valida el reclamo de las hijas de Zelofehad en Números 27:7. Jueces 12:6 lo usa para la pronunciación correcta. El cognado siríaco ke''n respalda este significado central de corrección verificada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106694, 'spa', 'Adverbio demostrativo que indica modo o grado', 'Adverbio demostrativo que indica modo o grado: ''así, de este modo, de esta manera''. Se encuentra principalmente en textos sapienciales y poéticos como Salmo 65:9, Proverbios 11:19, 15:7 y 28:2, y Eclesiastés 8:10. Aquí la palabra funciona como partícula comparativa o consecutiva en lugar de adjetivo, señalando cómo están o se siguen las cosas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106703, 'spa', 'Por tanto, por eso', 'Conjunción causal pleonástica que significa «por tanto, por esta razón, a causa de esto», empleada para vincular enfáticamente una acción declarada con su fundamento subyacente. En Génesis 18:5, Abraham insta a la hospitalidad porque (כִּי עַל כֵּן) ese es el propósito mismo de la llegada de los visitantes. La expresión duplica el marcador causal para lograr mayor peso retórico, con un matiz formal y arcaizante.');